const owners={label:"Nissan owner manuals and guides",url:"https://www.nissanusa.com/owners/ownership/manuals-guides.html",note:"Official model-year operating, warning, fuel and maintenance information"};
const service={label:"Nissan TechInfo",url:"https://www.nissan-techinfo.com/",note:"Official VIN-, model-, engine- and transmission-specific Electronic Service Manual information"};
const altimaP0101Old={label:"Nissan Bulletin NTB12-051k — 2011–2012 Altima P0101",url:"https://static.nhtsa.gov/odi/tsbs/2016/MC-10119172-9999.pdf",note:"Applies only with P0101, no drivability concern and a listed current ECM part number; covers listed QR25DE and VQ35DE Altimas"};
const altimaP0101_2016={label:"Nissan Bulletin NTB16-030 — 2016 Altima P0101",url:"https://static.nhtsa.gov/odi/tsbs/2016/SB-10075207-5448.pdf",note:"ECM reprogramming branch for a 2016 Altima with P0101, no drivability issue and a matching current ECM part number"};
const permanentDtc={label:"Nissan Bulletin NTB19-045b — permanent-DTC storage update",url:"https://static.nhtsa.gov/odi/tsbs/2020/MC-10171228-0001.pdf",note:"Lists defined 2015–2018 Altima VQ35DE P0101/P0448 applications; diagnosis and repair come first because the reprogram changes permanent-DTC storage, not the original fault"};
const evapTest={label:"Nissan Bulletin NTB13-097h — 2012-and-newer EVAP leak test",url:"https://static.nhtsa.gov/odi/tsbs/2020/MC-10184003-0001.pdf",note:"Uses CONSULT closure and pressure monitoring for P0442/P0455/P0456 and warns against replacing a cap or EVAP part when no leak is found"};
const ventOring={label:"Nissan Bulletin NTB17-082D — P0456 vent-valve O-ring leak",url:"https://static.nhtsa.gov/odi/tsbs/2021/MC-10190206-0001.pdf",note:"For applied 2008-and-newer Nissan vehicles only after the leak is confirmed at the vent-control-valve-to-canister seal"};
const p1778Four={label:"Nissan Bulletin NTB10-150a — 2010 QR25 Altima/Rogue P1778",url:"https://static.nhtsa.gov/odi/tsbs/2013/SB-10036734-3608.pdf",note:"Applies to 2010 QR25 Altima and 2010 Rogue; directs control-valve assembly replacement and applicable TCM reprogramming after the full procedure"};
const p1778V6={label:"Nissan Bulletin NTB11-002c — 2010 V6 Altima P1778",url:"https://static.nhtsa.gov/odi/tsbs/2013/MC-10192260-9999.pdf",note:"Separate 2010 VQ35DE Altima branch with flow-chart diagnosis, control-valve direction and TCM initialization instructions"};

const altima={name:"Nissan Altima",kicker:"NISSAN ALTIMA · ENGINE, EVAP AND CVT DIAGNOSTICS",breadcrumb:"Nissan Altima",about:"Nissan Altima engine, emissions and CVT diagnostics",yearsIntro:"Altima diagnostics span L31, L32, L33 and L34 generations with QR25DE, PR25DD, VQ35DE, KR20DDET and other market-specific engines, plus several conventional-automatic and CVT designs. Airflow learning, catalyst banks, valve timing, EVAP access and P1778 service strategy change across those boundaries. Confirm VIN, model year, engine, transmission code, current ECM/TCM part numbers and software before using a bulletin or diagram."};
const rogue={name:"Nissan Rogue",kicker:"NISSAN ROGUE · ENGINE, EVAP AND CVT DIAGNOSTICS",breadcrumb:"Nissan Rogue",about:"Nissan Rogue engine, emissions and CVT diagnostics",yearsIntro:"Rogue diagnostics span S35, T32 and T33 generations with QR25DE, PR25DD, KR15DDT, hybrid and market-specific powertrains, while Rogue Sport is a separate model. EVAP routing, MAF strategy, catalyst layout, valve timing and CVT hardware are not interchangeable. Confirm VIN, production model, engine, drivetrain, CVT code and calibration before applying a test or bulletin."};

export const troubleCodeAltima:TroubleCodeGuide[]=[
 make(altima,{code:"P0101",slug:"nissan/altima/p0101",title:"P0101 Code Nissan Altima: MAF Diagnosis and ECM Bulletin Checks",description:"Diagnose Altima P0101 using intake, fuel-trim and MAF tests plus exact 2011–2012, 2016 and VQ35DE bulletin boundaries.",definition:"Mass Air Flow Sensor Circuit Range/Performance",kind:"maf",quickAnswer:"P0101 means measured airflow did not agree with the Altima ECM's expected engine load; it does not prove the MAF sensor failed. Inspect the filter, duct, PCV and vacuum paths, smoke-test for unmetered air, compare MAF and fuel trims, then test the circuit. Nissan has narrow software branches for 2011–2012 and 2016 Altimas with no drivability concern and matching ECM part numbers. NTB19-045b separately changes permanent-DTC storage after repair on defined VQ35DE cars.",yearNotes:["NTB12-051k covers listed 2011–2012 L32 ECM part numbers and requires no drivability concern.","NTB16-030 covers 2016 L33 only when its ECM part number matches and drivability is normal.","NTB19-045b does not repair the original P0101; diagnosis comes first.","QR25DE, VQ35DE, PR25DD and VC-Turbo airflow strategies differ."],deepDive:[{heading:"Separate a clean-running software case from a real airflow fault",paragraphs:["Nissan's 2011–2012 and 2016 bulletins both require P0101 without drivability issues and an exact current ECM part-number match. Hesitation, stalling or rough idle sends the diagnosis back to the air path and circuit rather than directly to reprogramming.","Save MAF, calculated load, A/F ALPHA and self-learning values before cleaning anything. Compare idle with a controlled loaded condition so an intake leak can be distinguished from a sensor that under-reports as airflow rises."]},{heading:"Inspect the duct where engine movement opens it",paragraphs:["Flex the accordion section between the MAF and throttle body while looking for splits underneath, loose clamps and disconnected resonator or PCV branches. A crack may close at rest and open when the engine torques over.","Smoke-test the intake rather than spraying flammable cleaner. Repair leaks and verify MAF power, ground and signal before replacing the sensor, then use only sensor-safe cleaner if contamination is actually found."]},{heading:"Nissan learning procedures are part of completion",paragraphs:["Applicable reprogramming procedures call for throttle-valve closed-position, accelerator closed-position and idle-air-volume learning. Mechanical or throttle work may also disturb learned airflow, so follow the exact ESM sequence and prerequisites.","NTB19-045b is easily misread: Nissan states that its update changes how a permanent DTC is stored and erased, not the repair for P0101. Fix the measured fault first, then update only when model, engine, year and ECM part number all match."]}],sources:[altimaP0101Old,altimaP0101_2016,permanentDtc,service,owners]}),
 make(altima,{code:"P0420",slug:"nissan/altima/p0420",title:"P0420 Code Nissan Altima: Bank 1 Catalyst Diagnosis",description:"Diagnose Altima P0420 through misfire, fuel trim, oil consumption, exhaust leaks and sensor testing before converter replacement.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",kind:"catalyst",quickAnswer:"P0420 means Bank 1 catalyst oxygen-storage performance fell below the ECM threshold. On a four-cylinder Altima, Bank 1 is the only bank; on a VQ35DE V6, confirm bank location from the exact ESM. Repair P0300, P0171, injector imbalance, oil consumption and exhaust leakage first, then test A/F and rear O2 response under the monitor's conditions. Similar front and rear waveforms are evidence to analyze, not an automatic converter or sensor verdict.",yearNotes:["Four-cylinder Altimas have one cylinder bank; VQ35DE cars have Bank 1 and Bank 2.","P0430 on a V6 provides useful other-bank comparison.","Oil consumption and repeated misfire can permanently contaminate a catalyst.","Aftermarket exhaust leaks or low-quality converters can alter monitor results."],deepDive:[{heading:"Treat the converter as a possible victim",paragraphs:["Review permanent misfire and fuel-control codes, oil-addition history, coolant loss and plug deposits. A converter damaged by rich operation or oil ash will fail again if the upstream cause remains.","Stop sustained driving when the MIL flashes. Raw fuel from active misfire can overheat the close-coupled catalyst quickly, especially during highway load."]},{heading:"Use the other bank only when the engine has one",paragraphs:["A VQ35DE permits Bank 1 versus Bank 2 comparisons of trims and sensor behavior under identical load. The QR25DE and other inline-fours do not have a Bank 2 catalyst to use as a control.","Identify sensor position and bank through the VIN-correct exhaust diagram. Transverse-engine left/right descriptions are often ambiguous and can send parts to the wrong side of a V6."]},{heading:"Test exhaust integrity and sensor response",paragraphs:["Inspect the exhaust cold for soot, ticking or loose joints ahead of the rear sensor. Outside oxygen entering through a leak can change the monitor without restoring catalyst material.","Graph the front A/F sensor and rear O2 sensor through a stabilized drive after trims and misfire are corrected. Confirm repair only when readiness completes with no pending P0420."]}]}),
 make(altima,{code:"P0171",slug:"nissan/altima/p0171",title:"P0171 Code Nissan Altima: Lean Fuel-Trim Diagnosis",description:"Diagnose Altima P0171 with Nissan A/F ALPHA, self-learning, smoke, purge, MAF and fuel-delivery tests.",definition:"System Too Lean (Bank 1)",kind:"lean",quickAnswer:"P0171 means the Altima ECM added more fuel than its Bank 1 correction limit allowed. Save A/F ALPHA and self-learning values at idle and load before resetting them. Positive correction strongest at idle favors unmetered intake, PCV or purge air; correction that worsens with load favors MAF under-reporting or fuel delivery. Exhaust leaks, the upstream A/F sensor and injector balance remain test branches. Replacing the sensor because the code says lean skips the measurement that generated it.",yearNotes:["Inline-four Altimas use Bank 1 as their only bank; VQ35DE has two banks.","P0101 companion data makes MAF and intake-duct diagnosis a priority.","Direct-injection PR25DD and VC-Turbo fuel testing requires high-pressure precautions.","Nissan self-learning data should be saved before clearing."],deepDive:[{heading:"The trim shape localizes the missing fuel or extra air",paragraphs:["Record A/F ALPHA and long-term self-learning at warm idle, about 2,500 rpm and a controlled road load. A vacuum leak has a large effect when total airflow is low, while weak fuel delivery often becomes more visible as demand rises.","On a V6, compare banks under the same condition. One-bank correction suggests a local runner, injector, exhaust leak or A/F sensor path; both banks point more strongly toward MAF, purge, fuel supply or a shared intake leak."]},{heading:"Test the MAF and duct as one metered-air system",paragraphs:["Inspect the air-box seal, filter fit and flexible duct beneath the visible surface. A split after the MAF admits air that the ECM never counted and may set both P0101 and P0171.","Smoke-test intake and PCV paths, then verify purge closed-state sealing. Do not reset self-learning until the original numbers and code conditions have been recorded."]},{heading:"Fuel and A/F sensor conclusions require evidence",paragraphs:["Measure fuel pressure or commanded/actual pressure using the engine-specific safe procedure, and test injector contribution before blaming the pump. Direct-injection systems must be depressurized with factory precautions.","Inspect for exhaust leakage ahead of the upstream A/F sensor and verify sensor response. The page is repaired when correction stays near target through idle and load with no pending P0171, not merely when the lamp is cleared."]}]}),
 make(altima,{code:"P0300",slug:"nissan/altima/p0300",title:"P0300 Code Nissan Altima: Random Misfire Diagnostic Plan",description:"Diagnose Altima P0300 using cylinder counters, plugs, coils, fuel trims, injector balance and compression matched to the engine.",definition:"Random/Multiple Cylinder Misfire Detected",kind:"misfire",quickAnswer:"P0300 means multiple Altima cylinders misfired or no single cylinder dominated. Preserve P0301–P0306 counts, fuel trims, coolant temperature and load before moving components. A four-cylinder pattern across all cylinders suggests shared air, fuel, voltage or timing; a VQ35DE one-bank pattern narrows intake, fuel or cam causes. Inspect labeled plugs, make controlled ignition tests, then prove injector delivery and compression. A flashing MIL requires reducing load immediately to protect the catalysts.",yearNotes:["QR/PR/KR four-cylinder and VQ35DE cylinder layouts differ.","Direct-injection engines require fuel-pressure safety procedures.","P0171/P0101 companions raise shared air/fuel priority.","P0011/P0340 companions raise cam timing and synchronization priority."],deepDive:[{heading:"Do not erase the cylinder pattern",paragraphs:["Watch individual counters during the same cold start, idle or loaded condition in freeze frame. One leader supports targeted ignition, injector and mechanical testing, while several cylinders require a shared-system approach.","Label every plug and coil before removal. Moving several components at once destroys the controlled comparison and can hide an intermittent connector fault."]},{heading:"Plug deposits direct the second test",paragraphs:["Compare gap, porcelain, fuel wetness, oil ash and unusual steam cleaning across cylinders. A wet plug after a no-start, an oil-fouled plug and a uniformly worn set do not justify the same repair.","If a misfire does not follow one controlled ignition swap, return the known-good component and test injector contribution, intake leakage, compression and leak-down rather than continuing parts roulette."]},{heading:"Use fuel trims and cam codes to explain multi-cylinder faults",paragraphs:["Strong positive correction and P0101/P0171 move intake leaks, purge, MAF accuracy and fuel delivery higher. Normal trims with cam correlation codes or noise move valve timing and mechanical checks higher.","After repair, reproduce the original temperature and load while watching counters. Avoid repeated high-load drives with a flashing lamp because an unresolved Altima misfire can overheat the catalyst."]}]}),
 make(altima,{code:"P0456",slug:"nissan/altima/p0456",title:"P0456 Code Nissan Altima: Nissan EVAP Leak Test and Vent Seal",description:"Diagnose Altima P0456 with Nissan's CONSULT pressure test, purge check and confirmed vent-valve O-ring bulletin path.",definition:"EVAP System Very Small Leak Detected",kind:"evapSmall",quickAnswer:"P0456 means the Altima EVAP system failed a very-small-leak check; it does not automatically mean the cap is bad. Nissan NTB13-097h directs a CONSULT closure and pressure-retention test and says not to replace EVAP parts when no leak is detected. If smoke or pressure testing confirms leakage exactly where the vent-control valve mounts to the canister, NTB17-082D directs the vent-valve assembly repair for applicable 2008-and-newer Nissans. Purge, hoses and tank seals still need testing.",yearNotes:["NTB13-097h covers Nissan's 2012-and-newer P0442/P0455/P0456 test strategy.","NTB17-082D applies only after the vent-valve-to-canister seal is confirmed as the leak.","2017-and-older and 2018-and-newer Nissan test connections differ in NTB13-097h.","Fuel level and cold-soak conditions control when the monitor reruns."],deepDive:[{heading:"Follow Nissan's no-leak decision before ordering parts",paragraphs:["Document the cap before tightening it, then use CONSULT to close the vent valve and monitor the approved pressure tool. Nissan's flow chart says that a stable system with a non-leaking purge valve can indicate a previously loose cap.","In that no-leak branch, the bulletin explicitly warns against replacing the cap or another EVAP component. This prevents a temporary cap condition from becoming an unnecessary canister repair."]},{heading:"The vent O-ring path requires a located leak",paragraphs:["NTB17-082D is not permission to replace every Altima vent valve. It requires that the cap is not the cause and that leakage has been detected where the valve mounts to the canister, with the O-ring seal identified.","Use EVAP-safe pressure or smoke and inspect the actual plume. If it exits a hose, canister seam, filler or pump-module seal instead, repair the location the test found."]},{heading:"Test purge separately on newer connection layouts",paragraphs:["NTB13-097h distinguishes models with a service port from 2018-and-newer vehicles without one. On the latter path, Nissan connects at the purge line and calls for a separate purge-valve leak check.","After repair, meet fuel-level and soak requirements and verify no pending P0456. Road testing alone is not Nissan's confirmation procedure for this leak code."]}],sources:[evapTest,ventOring,service,owners]}),
 make(altima,{code:"P0448",slug:"nissan/altima/p0448",title:"P0448 Code Nissan Altima: EVAP Vent Circuit Diagnosis",description:"Diagnose Altima P0448 with vent-valve electrical, connector, airflow and leak tests plus the limited VQ35DE permanent-code update.",definition:"EVAP Canister Vent Control Valve Circuit Shorted",kind:"ventCircuit",quickAnswer:"P0448 is primarily an electrical diagnosis for the Altima EVAP canister vent-control circuit, although a mechanically stuck valve can also affect leak testing. Inspect the rear connector for water, corrosion and impact, test valve coil/current and loaded wiring, then verify airflow when commanded. NTB19-045b lists P0448 for defined 2015–2018 VQ35DE Altimas, but Nissan states its update changes permanent-DTC storage only after the original fault is diagnosed and repaired.",yearNotes:["NTB19-045b lists specified 2015–2018 Altima VQ35DE P0448 applications and ECM part numbers.","The bulletin does not repair the underlying vent circuit.","Four-cylinder and V6 canister locations and ECM calibrations differ.","P0456/P0455 companions add a separate sealing test."],deepDive:[{heading:"Circuit code and leak code ask different questions",paragraphs:["P0448 tests electrical behavior of the vent-control path; P0456 or P0455 tests whether the vapor system seals. The same valve participates in both, but one successful test does not automatically satisfy the other.","First verify coil resistance or current, power, ground/driver control and terminal condition. Then command the valve and prove that airflow actually changes rather than relying on an audible click."]},{heading:"Inspect the rear harness before condemning the ECM",paragraphs:["The canister area is exposed to water, road debris and prior exhaust or collision work. Look for green corrosion, backed-out pins, stretched wiring and a harness rubbed against a bracket.","Load-test the circuit from the correct schematic. A continuity beep through a damaged strand can miss the voltage drop that causes P0448 under operating current."]},{heading:"The permanent-code bulletin comes after repair",paragraphs:["NTB19-045b lists defined VQ35DE Altimas and specific ECM part numbers, but explicitly requires ESM diagnosis and repair first. The reprogram changes how a permanent DTC is stored and allowed to erase.","Do not flash a QR25DE car under the VQ35DE table or treat software as a substitute for a corroded connector. Confirm electrical command, valve airflow and any related EVAP monitor after the underlying repair."]}],sources:[permanentDtc,service,owners]}),
 make(altima,{code:"P0128",slug:"nissan/altima/p0128",title:"P0128 Code Nissan Altima: Thermostat and ECT Warm-Up Test",description:"Diagnose Altima P0128 with cold ECT comparison, coolant checks and a road-speed warm-up graph matched to the exact engine.",definition:"Coolant Thermostat Function",kind:"warmup",quickAnswer:"P0128 means Altima coolant temperature did not reach or regulate near the ECM's expected value. A leaking-open thermostat is common, but low coolant, trapped air, biased ECT data, unwanted fan operation or an incorrect thermostat can imitate it. After a long soak, compare ECT and intake-air temperature before starting; then graph ECT, speed, load, heater use and fan command. Use the exact QR25DE, VQ35DE, PR25DD or VC-Turbo cooling and bleeding procedure.",yearNotes:["Altima engine families use different thermostat housings and bleeding procedures.","A highway temperature drop strongly supports thermostat leakage.","The dashboard gauge is damped and cannot replace scan data.","Stop for overheating, steam, coolant loss or suddenly cold heater output."],deepDive:[{heading:"Cold-soak data tests the sensor before the thermostat",paragraphs:["ECT and intake-air temperature should approach ambient after an overnight soak. A large mismatch exists before coolant circulation begins, so sensor bias, connector resistance or stored heat deserves attention before replacing the thermostat.","Check level only when cold and inspect recent cooling-system work. Trapped air can produce unstable heater output and a misleading warm-up trace."]},{heading:"Graph the full drive instead of watching the gauge",paragraphs:["Plot temperature against time, speed, load, fan command and cabin heat. A slow climb followed by a repeatable fall during highway airflow is stronger thermostat evidence than a gauge that remains near its broad center range.","Compare commanded and actual fan behavior. A relay or control fault that runs fans when cold can remove enough heat to delay warm-up even when the thermostat closes."]},{heading:"Use the engine-correct part and verification",paragraphs:["QR, VQ, direct-injected PR and variable-compression engines do not share every cooling component or air-bleed step. Confirm engine and model year before opening the system.","After repair, verify stable scan temperature, consistent cabin heat and a completed monitor in comparable weather. Clearing P0128 immediately after installation is not proof."]}]}),
 make(altima,{code:"P0011",slug:"nissan/altima/p0011",title:"P0011 Code Nissan Altima: Intake Valve Timing Over-Advanced",description:"Diagnose Altima P0011 with oil, intake-timing solenoid, desired/actual cam and mechanical correlation tests.",definition:"Intake Valve Timing Control Performance (Bank 1)",kind:"vvtAdvance",quickAnswer:"P0011 means Bank 1 intake cam timing remained more advanced than commanded or failed Nissan's timing-control performance check. Verify oil level, viscosity, filter and pressure; save desired and actual cam angle; test the intake valve-timing control solenoid and circuit; then scope cam/crank relationship. A stuck oil-control path, phaser or mechanical timing fault can mimic a bad solenoid. P0340 or correlation codes change the order because feedback must be trustworthy.",yearNotes:["Inline-four Altimas use their only bank as Bank 1; VQ35DE bank location must be verified.","Variable-compression and direct-injection engines require exact service procedures.","Low/wrong oil or sludge can change hydraulic cam response.","Persistent chain rattle or low oil pressure requires limiting engine operation."],deepDive:[{heading:"Save commanded and actual angle before clearing",paragraphs:["Graph the intake cam target and measured position through idle and a controlled rpm change. A cam stuck advanced after command falls differs from a sensor signal that drops out or a phaser that merely responds slowly when oil is hot.","Record oil temperature, rpm and load from freeze frame. Reproducing those conditions safely matters because cold, thick oil and hot, thin oil can expose different hydraulic faults."]},{heading:"Test the oil-control path as a system",paragraphs:["Verify the exact oil specification, level, filter and mechanical pressure before commanding the solenoid. Then test circuit current and response rather than replacing the valve because it is accessible.","Inspect for debris or restricted passages only with the ESM procedure. Cleaning a solenoid cannot correct a worn phaser, damaged chain guide or low-pressure lubrication fault."]},{heading:"Cam feedback and mechanical timing are separate branches",paragraphs:["P0340, P0335 or waveform dropout makes measured angle unreliable and should be resolved first. Clean signals with a stable phase offset and rattle move mechanical timing or reluctor inspection higher.","Complete any required learning after repair and verify actual angle tracks command with no pending P0011. Do not use thicker oil to conceal noise or delay diagnosis."]}]}),
 make(altima,{code:"P0340",slug:"nissan/altima/p0340",title:"P0340 Code Nissan Altima: Cam Sensor Circuit Diagnosis",description:"Diagnose Altima P0340 with engine-specific sensor location, loaded circuit tests and cam/crank waveform comparison.",definition:"Camshaft Position Sensor Circuit (Bank 1)",kind:"cam",quickAnswer:"P0340 means the Altima ECM lost or rejected the Bank 1 cam-position signal; it does not prove the sensor itself. Confirm engine and connector, inspect harness routing, load-test power, ground and signal, then scope cam against crank. Missing or noisy edges support a sensor, connector or wiring fault. Clean signals with a stable phase error plus P0011 or timing noise point toward the valve-timing system, chain or reluctor rather than repeated sensor replacement.",yearNotes:["QR/PR/KR inline-four and VQ35DE sensor layouts differ.","Some Nissan cam and crank sensors may be physically similar; identify connectors before swapping.","P0011/P0016 companions raise mechanical or oil-control priority.","Repeated stalling or no-start makes diagnosis urgent."],deepDive:[{heading:"Verify which signal the ECM rejected",paragraphs:["Use the VIN-correct ESM connector view because engine families and harness routing changed across Altima generations. Read all codes for crank-sensor or shared-supply clues before disconnecting parts.","Inspect terminals for oil, corrosion and lost tension, especially near prior valve-cover or timing work. A connector that appears latched can still have a backed-out terminal."]},{heading:"Loaded electrical tests beat static continuity",paragraphs:["Verify power and ground while the circuit carries an appropriate load and scope the signal during cranking. A nearly broken wire can pass meter current yet lose waveform amplitude with heat or vibration.","If several sensors share power or ground and fail together, isolate branches systematically. Replacing every sensor leaves a common wiring fault untouched."]},{heading:"Waveform shape chooses electrical or mechanical work",paragraphs:["Intermittent missing edges or noise favor sensor, connector, air-gap or harness causes. Recreate the temperature and engine movement associated with the original event.","A repeatable offset between clean cam and crank patterns favors phaser, chain indexing or reluctor position. That measured relationship—not the code name—justifies opening the timing system."]}]}),
 make(altima,{code:"P1778",slug:"nissan/altima/p1778",title:"P1778 Code Nissan Altima: CVT Step Motor and Valve Body",description:"Diagnose Altima P1778 with CONSULT ratio data, fluid and circuit tests plus separate 2010 QR25DE and VQ35DE bulletin paths.",definition:"CVT Step Motor Function",kind:"cvtStep",quickAnswer:"P1778 means the Altima CVT could not achieve the expected step-motor or ratio-control response. Save TCM data, CVT temperature, primary/secondary speeds and companion codes before clearing; verify fluid by Nissan's temperature-based procedure and test circuits. For 2010 QR25 Altima, NTB10-150a directs a control-valve assembly and applicable TCM reprogramming after its flow chart. A separate NTB11-002c covers 2010 VQ35DE Altima and specifies its own initialization/reprogramming details. Neither applies to every year.",yearNotes:["NTB10-150a covers 2010 L32/CL32 QR25 Altima and 2010 Rogue.","NTB11-002c separately covers 2010 VQ35DE Altima.","Later CVTs use different valve bodies, calibration data and service strategies.","Slow acceleration after extended highway driving is a condition described in both 2010 bulletins."],deepDive:[{heading:"Preserve CVT data before cycling the ignition",paragraphs:["Record fluid temperature, commanded ratio, primary and secondary speed, step command, line-pressure data and all engine/transmission codes. A key cycle may change fail-safe behavior and erase the best comparison.","Do not reproduce poor acceleration in traffic or with heavy throttle. Use a controlled test and stop for severe shudder, overheating or inability to accelerate safely."]},{heading:"The two 2010 Altima bulletin paths are not identical",paragraphs:["NTB10-150a names the 2010 QR25 Altima and directs control-valve assembly replacement plus TCM reprogramming when applicable. NTB11-002c covers the 2010 VQ35DE Altima under a separate flow chart.","The V6 bulletin specifically distinguishes its TCM initialization requirements. Engine, CVT identification and current calibration therefore come before ordering a valve body or programming file."]},{heading:"P1778 does not automatically require a complete CVT",paragraphs:["Inspect fluid level and type at the specified temperature, electrical power/grounds, connectors and the ESM step-motor/ratio tests. Internal belt or pulley damage requires its own evidence.","After valve-body work, enter calibration data, reprogram and initialize exactly as the applicable procedure requires. Confirmation means commanded and actual ratio agree under the original condition with no returning P1778."]}],sources:[p1778Four,p1778V6,service,owners]}),
];

export const troubleCodeRogue:TroubleCodeGuide[]=[
 make(rogue,{code:"P0101",slug:"nissan/rogue/p0101",title:"P0101 Code Nissan Rogue: MAF and Intake Diagnosis",description:"Diagnose Rogue P0101 with air-duct, smoke, fuel-trim, MAF circuit and learning tests matched to the exact generation.",definition:"Mass Air Flow Sensor Circuit Range/Performance",kind:"maf",quickAnswer:"P0101 means the Rogue ECM judged measured airflow implausible for rpm, throttle and load; it is not a command to replace the MAF. Inspect the air filter and flexible duct, smoke-test intake, PCV and purge paths, compare MAF with A/F ALPHA and self-learning values, and load-test the circuit. S35 QR25DE, T32 QR25DE, Rogue Hybrid and T33 PR25DD or KR15DDT systems require different reference data and learning procedures. Do not apply Altima-only ECM bulletins to a Rogue.",yearNotes:["S35, T32 and T33 Rogue airflow strategies differ.","Rogue Sport is a separate model and must not be folded into Rogue bulletin coverage.","P0171 companion data makes unmetered air and MAF bias a shared priority.","Direct-injection and turbo engines require exact pressure and charge-air procedures."],deepDive:[{heading:"Inspect a moving crossover duct, not just the air box",paragraphs:["Flex the intake duct and inspect its underside, clamps, resonators and PCV connections. Engine movement can open a split that is invisible at rest and admit unmetered air downstream of the MAF.","On turbocharged applications, distinguish pre-turbo metered-air leaks from charge-air leaks using the correct low-pressure procedure. A QR25DE smoke-test setup is not automatically safe or complete for KR15DDT hardware."]},{heading:"Fuel trims make the airflow code measurable",paragraphs:["Save A/F ALPHA, self-learning, MAF, calculated load and throttle data at warm idle and controlled load. Lean correction strongest at idle supports a vacuum path; airflow that remains implausibly low as load rises supports MAF or duct measurement concerns.","Test power, ground and signal under load before cleaning or replacing the sensor. Contamination may be visible, but an intermittent ground or pin-fit fault cannot be washed away."]},{heading:"Use Rogue-specific learning and software information",paragraphs:["Nissan throttle and idle learning can be required after airflow, throttle or ECM work. Meet temperature, electrical-load and battery-voltage prerequisites from the exact ESM so a failed learn is not mistaken for a new defect.","Altima P0101 reprogramming bulletins list Altima models and ECM part numbers; they do not authorize a Rogue flash. Check Rogue VIN and current calibration through Nissan service information if physical and circuit tests pass."]}]}),
 make(rogue,{code:"P0420",slug:"nissan/rogue/p0420",title:"P0420 Code Nissan Rogue: Catalyst Efficiency Diagnosis",description:"Diagnose Rogue P0420 by correcting misfire, lean control, oil use and exhaust leaks before sensor or catalyst replacement.",definition:"Catalyst System Efficiency Below Threshold (Bank 1)",kind:"catalyst",quickAnswer:"P0420 means the Rogue Bank 1 catalyst did not show the expected oxygen-storage performance. Most four-cylinder Rogues have only Bank 1, but engine and hybrid/turbo configuration still control sensor layout. Repair P0300, P0171, MAF error, injector imbalance, oil consumption and exhaust leakage first. Then graph upstream A/F and downstream O2 response under the correct monitor conditions. A similar waveform does not by itself identify whether the catalyst, sensor or upstream combustion is responsible.",yearNotes:["Most Rogue engines are inline units with a single Bank 1, but exhaust and sensor packaging varies.","Rogue Hybrid and T33 turbo configurations require exact service information.","Oil consumption or repeated misfire can damage the converter.","A flashing MIL requires reducing load immediately."],deepDive:[{heading:"Resolve upstream evidence before evaluating storage",paragraphs:["Save permanent and pending misfire, fuel-trim and airflow codes. A catalyst monitor is interpreting exhaust produced by the engine; it cannot separate a deteriorated substrate from every rich, lean or misfire cause on its own.","Review oil additions, coolant level and plug deposits. Catalyst replacement without correcting fluid entry or injector imbalance invites a repeat failure."]},{heading:"Inspect the close-coupled exhaust cold",paragraphs:["Look for soot, ticking, damaged flex sections and loose joints ahead of the rear sensor. Outside oxygen entering through a leak can change the downstream signal and catalyst calculation.","If the Rogue has rattle or power loss, test for substrate damage and restriction using the ESM. Avoid prolonged operation when the converter may be overheating or blocked."]},{heading:"Run the monitor only after prerequisites pass",paragraphs:["Graph A/F and rear O2 behavior at the specified temperature and steady load after trims and misfire are stable. The downstream trace should be interpreted with the exact engine's control strategy.","A completed catalyst monitor without pending P0420 is the useful verification. Clearing codes resets readiness and can delay rather than prove the result."]}]}),
 make(rogue,{code:"P0171",slug:"nissan/rogue/p0171",title:"P0171 Code Nissan Rogue: Lean Condition Test Plan",description:"Diagnose Rogue P0171 with A/F ALPHA, self-learning, smoke, purge, MAF and fuel-pressure tests by engine generation.",definition:"System Too Lean (Bank 1)",kind:"lean",quickAnswer:"P0171 means the Rogue ECM reached excessive positive fuel correction on Bank 1. Save A/F ALPHA and self-learning at idle and load. Correction largest at idle supports unmetered intake, PCV or purge air; correction that grows under load supports insufficient fuel delivery or MAF under-reporting. Test exhaust integrity and upstream A/F response before replacing the sensor. T33 direct-injection and turbo engines require different pressure and air-path safety procedures from QR25DE Rogues.",yearNotes:["QR25DE, PR25DD and KR15DDT fuel and air systems differ.","Rogue Sport is not the same model for service procedures.","P0101 makes air-path and MAF validation especially important.","Direct-injection high-pressure fuel systems require factory depressurization precautions."],deepDive:[{heading:"Read correction at more than one operating point",paragraphs:["Record short-term A/F ALPHA and long-term self-learning at warm idle, raised rpm and a safe loaded condition. The change between those points is often more useful than the absolute number.","A vacuum leak has its greatest percentage effect at idle, while a restricted pump or injector supply can look acceptable at idle and lean out when demand rises."]},{heading:"Smoke the intake and prove purge closure",paragraphs:["Inspect the air duct, manifold, PCV plumbing and brake-booster path, then smoke-test with an engine-appropriate setup. Spraying cleaner around a running engine is less controlled and introduces fire risk.","Isolate the purge valve and watch trim response. A valve leaking manifold vacuum when commanded closed can create lean correction at idle and hard starting after refueling."]},{heading:"Do not confuse sensor report with sensor cause",paragraphs:["Check for exhaust leakage ahead of the upstream A/F sensor and verify response before replacement. The sensor may accurately be reporting extra oxygen from an intake leak, weak fuel delivery or misfire.","After repair, follow Nissan learning procedures where needed and verify correction stays near target through the original conditions with no pending P0171."]}]}),
 make(rogue,{code:"P0300",slug:"nissan/rogue/p0300",title:"P0300 Code Nissan Rogue: Random Misfire Diagnosis",description:"Diagnose Rogue P0300 using cylinder counters, plug and coil evidence, trims, injector tests and compression matched to the engine.",definition:"Random/Multiple Cylinder Misfire Detected",kind:"misfire",quickAnswer:"P0300 means multiple Rogue cylinders misfired or the ECM could not isolate one dominant cylinder. Preserve P0301–P0304 counts, trims, temperature and load before moving coils. A single leader needs plug, ignition, injector and compression testing; all cylinders point toward shared MAF/air leakage, purge, fuel supply, voltage or timing. Direct-injected PR25DD and turbo KR15DDT engines add high-pressure and charge-air branches not used on older QR25DE models.",yearNotes:["S35/T32 QR25DE and T33 engines use different fuel and ignition procedures.","P0101/P0171 companions prioritize shared air and fuel evidence.","P0011/P0340 companions prioritize timing and cam feedback.","A flashing MIL can rapidly damage the catalyst."],deepDive:[{heading:"Preserve the cylinder structure",paragraphs:["Watch individual misfire counts during the exact cold start, idle or load from freeze frame. One cylinder supports a controlled component comparison; several equal cylinders support a shared-system test.","Label plugs and coils before moving one item. Swapping an entire set makes it impossible to know whether the fault followed a component or disappeared with changed conditions."]},{heading:"Compare plug evidence before installing new parts",paragraphs:["Examine gap, insulator, raw-fuel wetness, oil ash and unusual cleaning. Compare cylinders while keeping each plug identified so injector and mechanical evidence is not mixed together.","If the count remains after one controlled ignition test, return the known-good component and measure injector contribution, compression and leak-down. Do not assume every Rogue misfire is ignition."]},{heading:"Shared air and fuel faults often leave trim clues",paragraphs:["Positive correction with P0101 or P0171 supports intake leakage, purge, MAF bias or fuel-delivery testing. Cam codes or rattle change priority toward VVT and mechanical synchronization.","Verify under the original conditions without forcing a flashing-MIL road test. Stable counters and no pending misfire after readiness operation provide stronger proof than a temporarily smooth idle."]}]}),
 make(rogue,{code:"P0456",slug:"nissan/rogue/p0456",title:"P0456 Code Nissan Rogue: EVAP Leak and Vent O-Ring Tests",description:"Diagnose Rogue P0456 with Nissan's pressure-retention flow chart, purge testing and confirmed vent-valve seal path.",definition:"EVAP System Very Small Leak Detected",kind:"evapSmall",quickAnswer:"P0456 means the Rogue EVAP system detected a very small leak. Preserve cap condition and fuel level, then follow Nissan's CONSULT closure and pressure-retention procedure rather than replacing the cap by assumption. NTB17-082D applies only when testing confirms leakage at the vent-control-valve-to-canister O-ring on an applicable 2008-and-newer Nissan. Purge leakage, hoses, canister seams and tank-module seals remain separate possibilities, and T33 routing differs from S35/T32.",yearNotes:["NTB13-097h provides Nissan's 2012-and-newer P0456 leak-test flow chart.","NTB17-082D requires a confirmed leak at the vent-valve mounting seal.","2018-and-newer Nissan vehicles use the bulletin's no-service-port connection path.","Rogue Sport must be identified separately from Rogue."],deepDive:[{heading:"Nissan's flow chart prevents cap guessing",paragraphs:["Record whether the cap was secured before anyone touches it, then command vent closure and monitor the approved pressure tool. If pressure remains stable and purge does not leak, Nissan identifies a previously loose cap as the possible cause.","That no-leak branch says not to replace the cap or another EVAP component. Preserve this decision instead of turning every P0456 into a parts sale."]},{heading:"Confirm the vent seal before using its bulletin",paragraphs:["NTB17-082D requires a detected leak exactly where the vent-control valve attaches to the canister and identification of the O-ring as the cause. It is not a blanket vent-valve replacement instruction.","Use regulated EVAP equipment and inspect the smoke location. Road damage, a hose connection, canister seam or top-of-tank seal requires the repair the plume actually supports."]},{heading:"Connection strategy changes on later models",paragraphs:["NTB13-097h separates service-port vehicles from 2018-and-newer models without a port. The newer path connects at the purge line and calls for a separate purge-valve leak check.","After repair, allow correct fuel level and soak conditions and confirm no pending P0456. Repeated road testing is not the pressure-test procedure Nissan specifies."]}],sources:[evapTest,ventOring,service,owners]}),
 make(rogue,{code:"P0448",slug:"nissan/rogue/p0448",title:"P0448 Code Nissan Rogue: EVAP Vent Control Circuit",description:"Diagnose Rogue P0448 through rear connector, vent-valve coil, driver circuit and mechanical airflow tests by generation.",definition:"EVAP Canister Vent Control Valve Circuit Shorted",kind:"ventCircuit",quickAnswer:"P0448 means the Rogue ECM detected an electrical fault in the EVAP vent-control circuit. Inspect the rear canister connector and harness for water, corrosion, impact and chafe; test coil resistance/current and loaded power/driver control; then command the valve and verify airflow. A valve can be electrically healthy but mechanically stuck, while a P0456 companion requires a separate sealing test. Do not use an Altima VQ35DE permanent-DTC bulletin on a Rogue.",yearNotes:["S35, T32 and T33 canister placement and harness routing differ.","P0448 is a circuit code even though the vent valve also affects leak testing.","P0456/P0455 companions require pressure or smoke testing after circuit repair.","Rogue Sport and Rogue Hybrid require exact model identification."],deepDive:[{heading:"Rear exposure makes connector evidence valuable",paragraphs:["The vent valve sits near the canister and is exposed to water, salt, road debris and underbody work. Inspect terminal color, grip, seals and harness support before measuring through the circuit.","Look for wiring pinched after canister, exhaust, fuel-tank or collision repair. Load-testing is more reliable than a continuity beep through a partially broken strand."]},{heading:"Electrical command and airflow are different tests",paragraphs:["Measure coil and driver behavior against the exact ESM, then command the valve with CONSULT. Current or clicking proves electrical activity but not that the passage opens and closes freely.","If P0456 or P0455 is stored, repair P0448 and then perform Nissan's separate EVAP pressure-retention test. A circuit repair does not prove the entire vapor system seals."]},{heading:"Do not import another Nissan model's software path",paragraphs:["NTB19-045b lists selected Altima, Rogue Sport and Rogue Hybrid combinations but does not generically list every Rogue P0448. Model identity, engine, year and ECM part number are hard boundaries.","For a standard Rogue outside a named bulletin, follow the ESM circuit and valve tests. Confirm correct command, current, airflow and readiness with no pending P0448."]}]}),
 make(rogue,{code:"P0128",slug:"nissan/rogue/p0128",title:"P0128 Code Nissan Rogue: Thermostat Warm-Up Diagnosis",description:"Diagnose Rogue P0128 with cold ECT comparison, coolant checks and a road-load warm-up graph matched to QR, PR or KR engines.",definition:"Coolant Thermostat Function",kind:"warmup",quickAnswer:"P0128 means Rogue coolant temperature did not rise or regulate as expected. A thermostat leaking open is common, but low coolant, air after service, biased ECT data, unwanted fan operation or an incorrect thermostat can imitate it. Compare ECT and intake-air temperature after a long soak, then graph temperature, speed, load, heater demand and fan command. QR25DE, PR25DD, KR15DDT and hybrid cooling systems require their own parts and bleeding procedures.",yearNotes:["S35/T32 QR25DE and T33 engines use different cooling layouts.","Hybrid thermal-management procedures require exact service information.","Highway temperature drop strongly supports a leaking-open thermostat.","Stop for overheating, steam, coolant loss or suddenly cold heater output."],deepDive:[{heading:"Test sensor plausibility before circulation begins",paragraphs:["After an overnight soak, ECT and intake-air temperature should be close to ambient. A large key-on difference points toward sensor or circuit bias because the thermostat has not yet influenced warm-up.","Inspect cold coolant level and recent service history. Air trapped after pump, hose or engine work can produce unstable heat and temperature readings."]},{heading:"Use a graph that includes road and fan conditions",paragraphs:["Plot ECT against time, vehicle speed, engine load, fan command and cabin heat. A temperature rise that reverses during steady road airflow is more useful than the damped dashboard gauge.","Confirm whether fans are commanded. An electrical or control fault that runs them cold can delay warm-up while an otherwise functional thermostat remains closed."]},{heading:"Finish with the generation-correct bleed procedure",paragraphs:["Do not assume a T32 QR25DE thermostat, fill point or bleed sequence applies to a T33 turbo or hybrid system. Identify VIN, engine and drivetrain before draining coolant.","Verification requires stable scan temperature and cabin heat under comparable conditions plus no pending P0128 after the monitor runs."]}]}),
 make(rogue,{code:"P0011",slug:"nissan/rogue/p0011",title:"P0011 Code Nissan Rogue: Intake Timing Over-Advanced",description:"Diagnose Rogue P0011 with oil, VVT solenoid, desired/actual cam and mechanical correlation tests matched to the engine.",definition:"Intake Valve Timing Control Performance (Bank 1)",kind:"vvtAdvance",quickAnswer:"P0011 means the Rogue Bank 1 intake cam remained more advanced than commanded or failed its timing-control performance check. Verify oil level, grade, filter and pressure, save desired/actual angle, test the intake timing solenoid and circuit, then compare cam and crank signals. A restricted oil path, phaser, chain or feedback fault can imitate a failed solenoid. QR25DE, PR25DD and KR15DDT VVT systems require separate service data.",yearNotes:["Rogue inline engines use their only bank as Bank 1, but control hardware changes by engine.","Low/wrong oil and sludge can affect hydraulic timing response.","P0340 or correlation codes make cam feedback a priority.","Rattle, stalling or an oil-pressure warning requires limiting operation."],deepDive:[{heading:"Commanded versus actual timing defines the symptom",paragraphs:["Save the intake cam target and measured angle through idle and a controlled rpm change. A cam that stays advanced after command falls differs from intermittent sensor dropout or a phaser that responds slowly only with hot oil.","Record oil temperature, load and rpm so the fault can be reproduced without guessing. Do not command repeated high-rpm tests when pressure or timing noise is questionable."]},{heading:"Oil and solenoid checks come before internal parts",paragraphs:["Verify exact viscosity, level, filter and mechanical pressure. Then test solenoid current, wiring and response; a clean electrical command with no hydraulic movement points to a different branch than an open coil.","Inspect screens or passages only by the engine-specific ESM. Debris may indicate a broader lubrication issue that cleaning one valve will not solve."]},{heading:"Scope feedback before judging the chain",paragraphs:["Resolve P0340/P0335 and any shared-circuit problem so measured cam angle is trustworthy. Intermittent waveform loss favors electrical diagnosis.","A stable offset with clean signals, rattle or failed phaser control supports mechanical timing inspection. Complete required learning and verify actual timing tracks command with no pending P0011."]}]}),
 make(rogue,{code:"P0340",slug:"nissan/rogue/p0340",title:"P0340 Code Nissan Rogue: Cam Sensor Circuit Tests",description:"Diagnose Rogue P0340 with exact sensor identification, loaded wiring checks and cam/crank scope comparison by engine generation.",definition:"Camshaft Position Sensor Circuit (Bank 1)",kind:"cam",quickAnswer:"P0340 means the Rogue ECM lost or rejected the expected Bank 1 cam-position signal; it does not prove the sensor failed. Identify the QR25DE, PR25DD, KR15DDT or hybrid circuit, inspect connector and harness routing, load-test power, ground and signal, then scope cam against crank. Missing/noisy edges favor a circuit or sensor path; clean signals with stable phase error plus P0011 or rattle favor oil-control or mechanical timing inspection.",yearNotes:["S35, T32 and T33 engine and connector layouts differ.","Rogue Sport is a separate platform with separate service data.","P0011/P0016 companion codes change diagnostic priority.","Repeated stalling, long crank or no-start warrants prompt diagnosis."],deepDive:[{heading:"Identify the engine before identifying the sensor",paragraphs:["Use VIN and the correct ESM connector view. A location or pinout for an S35 QR25DE should not be used on a T33 direct-injection or turbo engine.","Inspect harness areas disturbed by valve-cover, high-pressure fuel or timing work. Look for backed-out terminals, oil contamination and wires pulled tight around brackets."]},{heading:"Test the circuit under operating load",paragraphs:["Verify power and ground with appropriate load and capture the signal during crank and idle. Static resistance can appear normal through a connection that fails with heat or engine vibration.","Multiple sensor codes may share a supply or ground. Isolate the common branch before replacing several components that are all receiving the same bad voltage."]},{heading:"Waveform evidence separates sensor from timing",paragraphs:["Missing edges, noise or amplitude collapse support sensor, connector, air-gap or harness faults. Recreate the temperature recorded when possible.","A clean but consistently displaced cam pattern relative to crank supports phaser, chain or reluctor investigation. That measured offset—not P0340 wording alone—justifies mechanical work."]}]}),
 make(rogue,{code:"P1778",slug:"nissan/rogue/p1778",title:"P1778 Code Nissan Rogue: CVT Step Motor Diagnosis",description:"Diagnose Rogue P1778 with CONSULT ratio data, fluid and circuit testing plus the exact 2010 S35 valve-body bulletin boundary.",definition:"CVT Step Motor Function",kind:"cvtStep",quickAnswer:"P1778 means the Rogue CVT did not achieve the expected step-motor or ratio-control response. Preserve fluid temperature, primary/secondary speed, commanded ratio and companion codes; verify fluid with Nissan's temperature-based procedure and test power, grounds and valve-body control. NTB10-150a applies specifically to the 2010 S35 Rogue and directs control-valve assembly replacement plus applicable TCM reprogramming after its full procedure. Later Rogue CVTs require their own ESM and calibration strategy.",yearNotes:["NTB10-150a specifically lists 2010 Rogue S35.","S35, T32 and T33 transmissions do not share every valve body or programming step.","Slow acceleration after extended highway driving is a bulletin-described condition.","Rogue Sport is a different model and must not inherit Rogue CVT instructions."],deepDive:[{heading:"Capture ratio-control evidence before reset",paragraphs:["Save CVT fluid temperature, commanded and actual ratio, primary and secondary speeds, step command, pressure data and every engine/transmission code. Cycling the ignition may alter fail-safe and remove the best symptom snapshot.","Reproduce only in a controlled setting. Slow launch after highway operation can be unsafe in traffic, and severe shudder or overheat warnings require stopping."]},{heading:"The 2010 bulletin is a precise repair path",paragraphs:["NTB10-150a names the 2010 Rogue S35 and the P1778/slow-acceleration condition. Its action is control-valve assembly replacement and TCM reprogramming when the service-procedure part-number check applies.","That instruction does not automatically transfer to a 2011–2020 Rogue, Rogue Sport or another CVT. Identify transmission and current TCM calibration before ordering parts."]},{heading:"A complete transmission is not the first assumption",paragraphs:["Use Nissan's fluid-level and condition procedure, electrical tests and ESM step-motor diagnosis. Valve-body hydraulics, wiring and control must be separated from confirmed belt or pulley damage.","After repair, enter calibration data and perform reprogramming/initialization exactly as required. Correct ratio response under the original condition with no returning P1778 is the verification."]}],sources:[p1778Four,service,owners]}),
];
